// Use this many pixels at the bottom to show a binary counter of generation number
#define CounterHeight (int(floor(iResolution.y / 20.0)))
#define CounterBitWidth (int(floor(iResolution.x / 32.0)))

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    ivec2 UV = ivec2(fragCoord);

    // fragColour = BUFF(UV); return; //DEBUG ************ raw view of buffer
    // fragColour = vec4(floor(fract(iDate.w) / 1.0 * iResolution.x / fragCoord.x)); return; // DEBUG ********
    // fragColour = vec4(texture(iChannel0, fragCoord / iResolution.xy).x * 10000.0); return; // DEBUG


    // Normalized pixel coordinates (from 0 to 1)
    // vec2 uv = fragCoord/iResolution.xy;

    // This will be the output
    vec4 cout = vec4(0.0, 0.0, 0.0, 1.0); // (black)

    int count = GETINT(COUNTER);

    if (UV.y < CounterHeight) { // binary rep of count (red)
        int bit = int(floor(fragCoord.x / float(CounterBitWidth))); // which bit?
        if (UV.x % CounterBitWidth == 0) {
            // Bit dividers
            cout.g = (bit % 4 == 0) ? 1.0 : 0.2;
        } else if (((count >> bit) & 1) > 0) { 
            cout.r = 1.0; // bit set
        }
    } else if (fragCoord.y > float(CounterHeight)) { // cell grid (white/black)
        int i = int(fragCoord.x * float(GRIDW) / iResolution.x);
        int j = int(  (fragCoord.y - float(CounterHeight)) * float(GRIDH) 
                    / (iResolution.y - float(CounterHeight)));
        ivec2 IJ = ivec2(i, j);
        if (gridIJValid(IJ)) {
            cout =   (GETINT(gridLocOfIJ(IJ)) != 0) 
                   ? vec4(1.0, 1.0, 1.0, 1.0)  // WHITE
                   : vec4(0.5, 0.0, 0.0, 1.0); // DARK RED
        } else {
            cout = vec4(1.0, 0.0, 1.0, 1.0); // MAGENTA       
        }
    } else { // dynamic GREEN -> CYAN
        cout = vec4(0.0, 1.0, float(GETINT(COUNTER)) / 100.0, 1.0);
    }


    fragColour = cout;
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    ivec2 loc = ivec2(fragCoord);
    vec4 next = BUFF(loc);
    fragColour = next; // anything not set later will be the same as last time.

    // fragColour = vec4(iDate.x); return; // DEBUG ********

    if (loc == ENTROPY) {
        fragColour = fract(BUFF(ENTROPY) + iTime + iDate.w * 2.4374533 + 0.7856936);
        return;
    }

    // Initialise at start, or when space bar is pressed .  
    // 4 frames gives time for some entropy to build up.
    if (iFrame < 4 || texelFetch(iChannel3, ivec2(32, 1), 0).x > 0.0) {         // Initialise

        if (loc == COUNTER) {
            next = SETINT(0U);
        } else {
          ivec2 ij = gridIJOfLoc(loc);
          if (gridIJValid(ij)) {
              //next = SETINT( (IJ.x == 5 || IJ.y == 5) ? 1 : 0);
              next =  SETINT(fract((27.23456789 + BUFF(ENTROPY).x) * fragCoord.x / (1.0 + fragCoord.y) * 14735.5) < 0.5 ? 0 : 1);  
          } else {
              next = SETINT(0);
              next.b = 1.0;
              next.a = 1.0;
            //  next = vec4(0.0,0.0,1.0,1.0); // Blue
          }
        }

    } else {        // Update 
        // fragColour = next; return; // DEBUG ********* freeze after init

        if (loc == COUNTER) {
            next = SETINT(GETINT(COUNTER) + 1);
        } else {
            ivec2 IJ = gridIJOfLoc(loc);    
            if (gridIJValid(IJ)) {

                int prev = GETINT(gridLocOfIJ(IJ));
                int count = -prev;
                for (int di = -1; di < 2; ++di) {
                    for (int dj = -1; dj < 2; ++dj) {
                        count += (GETINT(gridLocOfIJ(IJ + ivec2(di, dj))) > 0 ? 1 : 0);
                    }
                }
                next = SETINT((count == 3 || (count == 2 && prev > 0)) ? 1 : 0);
            } else {
                next = SETINT(0); // vec4(1.0,1.0,0.0,1.0); // YELLOW
            }
        }

    }

    fragColour = next;
}

#define BUFF(uv) texelFetch(iChannel0, ivec2(uv), 0)

#define ENTROPY ivec2(1, 0)
#define COUNTER ivec2(0, 0)

// grid has a border of width 1 around it that is undefined
#define GRID00 ivec2(11, 11)
#define GRIDW 400
#define GRIDH 400
ivec2 gridLocOfIJ(ivec2 ij) { return GRID00 + ij; }
bool gridIJValid(ivec2 ij) { return (0 <= ij.x && ij.x < GRIDW && 0 <= ij.y && ij.y < GRIDH); }
ivec2 gridIJOfLoc(ivec2 loc) { return ivec2(loc.x - GRID00.x, loc.y - GRID00.y); }


// These don't work on my mobile device:
//#define GETINT(loc) int(packSnorm2x16(BUFF(loc).xy))
//#define SETINT(value) vec4(unpackSnorm2x16(uint(value)), 0.0, 0.0)

// So instead, just round the floats to integers.  Sigh.
#define GETINT(loc) (int(round(BUFF(loc).x)))
#define SETINT(value) vec4(round(float(value)), 0.0, 0.0, 0.0)
